'use client';

import { useEffect, useMemo, useState } from 'react';
import { ArrowRight, Clapperboard, Play, Search, Sparkles, Star, X } from 'lucide-react';
import type { MovieboxItem } from '@/lib/moviebox';
import { toDisplayTitle, toPosterUrl } from '@/lib/moviebox';

const FALLBACK_POSTER = 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&w=800&q=80';

type MovieboxSection = {
  section: string;
  count?: number;
  items: MovieboxItem[];
};

export default function HomePage() {
  const [sections, setSections] = useState<MovieboxSection[]>([]);
  const [search, setSearch] = useState('');
  const [searchResults, setSearchResults] = useState<MovieboxItem[]>([]);
  const [selectedItem, setSelectedItem] = useState<MovieboxItem | null>(null);
  const [detail, setDetail] = useState<Record<string, unknown> | null>(null);
  const [streamUrl, setStreamUrl] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadHome = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('/api/moviebox/home', { cache: 'no-store' });
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.error || 'Unable to load homepage');
      }

      const normalizedSections = Array.isArray(data.sections) ? data.sections : [];
      setSections(normalizedSections);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'Failed to load content');
    } finally {
      setLoading(false);
    }
  };

  const fetchSearch = async (keyword: string) => {
    try {
      const response = await fetch(`/api/moviebox/search?q=${encodeURIComponent(keyword)}`);
      const data = await response.json();
      const items = Array.isArray(data.items) ? data.items : [];
      setSearchResults(items);
    } catch {
      setSearchResults([]);
    }
  };

  const handleSearchChange = async (nextValue: string) => {
    setSearch(nextValue);
    const trimmed = nextValue.trim();

    if (!trimmed) {
      setSearchResults([]);
      return;
    }

    await fetchSearch(trimmed);
  };

  const openDetails = async (item: MovieboxItem) => {
    const slug = String(item.slug || item.detailPath || item.name || item.title || '');
    if (!slug) return;

    setSelectedItem(item);
    setAiSummary('');

    try {
      const response = await fetch(`/api/moviebox/detail/${encodeURIComponent(slug)}`);
      const data = await response.json();
      const nextDetail = (data?.data ?? data) as Record<string, unknown>;
      setDetail(nextDetail);

      const aiResponse = await fetch('/api/ai/describe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: toDisplayTitle(item),
          description: typeof nextDetail?.description === 'string' ? nextDetail.description : String(nextDetail?.synopsis || item.badge || 'Premium streaming content'),
          genre: Array.isArray(nextDetail?.genres) ? String(nextDetail.genres[0] || '') : item.badge || 'Streaming',
        }),
      });
      const aiData = await aiResponse.json();
      if (aiData?.text) setAiSummary(aiData.text);
    } catch {
      setDetail({ title: toDisplayTitle(item) } as Record<string, unknown>);
      setAiSummary('This title delivers a premium, binge-worthy viewing experience built for momentum, atmosphere, and strong character arcs.');
    }
  };

  useEffect(() => {
    const timeout = window.setTimeout(() => {
      void loadHome();
    }, 0);

    return () => window.clearTimeout(timeout);
  }, []);

  const playItem = async (item: MovieboxItem) => {
    const subjectId = item.subject_id ? String(item.subject_id) : '';
    const detailPath = item.slug || item.detailPath || '';

    if (!subjectId) return;

    try {
      const response = await fetch(
        `/api/moviebox/stream/${encodeURIComponent(subjectId)}?detail_path=${encodeURIComponent(detailPath)}&se=0&ep=0`,
      );
      const data = await response.json();
      const source = data?.sources?.[0]?.url || data?.hls?.[0]?.url || data?.dash?.[0]?.url || null;
      setStreamUrl(source);
      setSelectedItem(item);
    } catch {
      setStreamUrl(null);
    }
  };

  const featuredBanner = useMemo(
    () => sections.find((section) => section.section.toLowerCase() === 'banner')?.items?.[0],
    [sections],
  );

  const allItems = useMemo(() => sections.flatMap((section) => section.items || []), [sections]);

  return (
    <main className="relative min-h-screen px-4 pb-16 pt-6 md:px-8 lg:px-10">
      <div className="mx-auto max-w-7xl">
        <header className="glass-panel sticky top-4 z-30 mb-8 flex items-center justify-between gap-4 rounded-2xl px-4 py-3 md:px-6">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-cyan-500 text-lg font-black text-white shadow-lg shadow-violet-500/30">
              G
            </div>
            <div>
              <div className="text-xs uppercase tracking-[0.3em] text-[var(--muted-foreground)]">Premium</div>
              <div className="text-xl font-bold text-[var(--foreground)]">GemiFlix</div>
            </div>
          </div>

          <label className="hidden min-w-[18rem] items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-sm text-[var(--muted-foreground)] md:flex">
            <Search className="h-4 w-4" />
            <input
              value={search}
              onChange={(event) => {
                void handleSearchChange(event.target.value);
              }}
              placeholder="Search movies & series"
              className="w-full bg-transparent text-[var(--foreground)] outline-none placeholder:text-[var(--muted-foreground)]"
            />
          </label>

          <div className="rounded-full border border-white/10 bg-white/5 px-3 py-1.5 text-xs font-medium text-[var(--muted-foreground)]">
            Live backend: Moviebox API
          </div>
        </header>

        {error && (
          <div className="glass-panel mb-6 rounded-2xl border border-red-500/30 bg-red-500/5 p-4 text-sm text-red-200">
            {error}
          </div>
        )}

        {search.trim() && (
          <section className="mb-8">
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-xl font-semibold text-[var(--foreground)]">Search results</h2>
              <button
                className="text-sm text-[var(--muted-foreground)] transition hover:text-[var(--foreground)]"
                onClick={() => {
                  setSearch('');
                  setSearchResults([]);
                }}
              >
                Clear
              </button>
            </div>

            {searchResults.length === 0 ? (
              <div className="glass-panel rounded-2xl p-6 text-sm text-[var(--muted-foreground)]">
                No matches found for “{search}”.
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-5">
                {searchResults.map((item) => (
                  <PosterCard
                    key={`${item.subject_id ?? item.slug ?? toDisplayTitle(item)}`}
                    item={item}
                    onOpen={() => openDetails(item)}
                    onPlay={() => playItem(item)}
                  />
                ))}
              </div>
            )}
          </section>
        )}

        {!search.trim() && (
          <>
            <section className="mb-8 overflow-hidden rounded-[2rem] border border-white/10 bg-black/20">
              <div className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
                <div className="relative min-h-[420px] overflow-hidden">
                  <img
                    src={toPosterUrl(featuredBanner ?? { poster_url: FALLBACK_POSTER })}
                    alt={toDisplayTitle(featuredBanner ?? { name: 'Featured movie' })}
                    className="h-full w-full object-cover"
                  />
                  <div className="absolute inset-0 bg-gradient-to-r from-black via-black/70 to-transparent" />
                  <div className="absolute inset-x-0 bottom-0 p-6 md:p-8">
                    <div className="mb-3 inline-flex items-center gap-2 rounded-full border border-violet-400/40 bg-violet-500/20 px-3 py-1 text-[11px] uppercase tracking-[0.25em] text-violet-100">
                      <Sparkles className="h-3.5 w-3.5" />
                      Featured
                    </div>
                    <h1 className="max-w-lg text-3xl font-black tracking-tight text-white md:text-5xl">
                      {toDisplayTitle(featuredBanner ?? { name: 'Featured title' })}
                    </h1>
                    <div className="mt-4 flex flex-wrap items-center gap-4 text-sm text-zinc-200">
                      <span className="inline-flex items-center gap-1.5">
                        <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                        {featuredBanner?.rating ?? '8.9'}
                      </span>
                      <span>{featuredBanner?.year ?? '2026'}</span>
                      <span className="rounded-full border border-white/10 px-2 py-0.5">{featuredBanner?.badge || 'HD'}</span>
                    </div>
                    <div className="mt-6 flex gap-3">
                      <button
                        onClick={() => playItem(featuredBanner ?? { subject_id: '', slug: '', name: 'Featured title' })}
                        className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-3 text-sm font-semibold text-black transition hover:scale-[1.02]"
                      >
                        <Play className="h-4 w-4 fill-current" />
                        Watch now
                      </button>
                      <button
                        onClick={() => openDetails(featuredBanner ?? { name: 'Featured title' })}
                        className="inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/5 px-5 py-3 text-sm font-semibold text-white backdrop-blur-sm transition hover:bg-white/10"
                      >
                        View details
                        <ArrowRight className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                </div>

                <div className="flex flex-col justify-center gap-4 p-6">
                  <div className="flex items-center gap-2 text-sm uppercase tracking-[0.26em] text-[var(--muted-foreground)]">
                    <Clapperboard className="h-4 w-4" />
                    Top action
                  </div>

                  {allItems.slice(0, 4).map((item) => (
                    <button
                      key={`${item.subject_id ?? item.slug ?? toDisplayTitle(item)}`}
                      onClick={() => openDetails(item)}
                      className="glass-card group flex items-center gap-3 rounded-2xl p-2 text-left transition hover:border-violet-400/30"
                    >
                      <img src={toPosterUrl(item)} alt={toDisplayTitle(item)} className="h-20 w-16 rounded-xl object-cover" />
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-sm font-semibold text-[var(--foreground)]">{toDisplayTitle(item)}</div>
                        <div className="mt-1 flex items-center gap-2 text-xs text-[var(--muted-foreground)]">
                          <span>{item.year ?? '2026'}</span>
                          <span>•</span>
                          <span>{item.badge || 'HD'}</span>
                        </div>
                      </div>
                      <Play className="h-4 w-4 text-violet-300 transition group-hover:translate-x-0.5" />
                    </button>
                  ))}
                </div>
              </div>
            </section>

            {loading ? (
              <div className="mb-8 grid gap-4 md:grid-cols-3">
                {Array.from({ length: 6 }).map((_, index) => (
                  <div key={index} className="glass-panel h-80 animate-pulse rounded-2xl bg-white/5" />
                ))}
              </div>
            ) : (
              sections.map((section) => (
                <section key={section.section} className="mb-8">
                  <div className="mb-4 flex items-center justify-between gap-3">
                    <h2 className="text-xl font-semibold text-[var(--foreground)]">{section.section}</h2>
                    <button className="inline-flex items-center gap-2 text-sm text-[var(--muted-foreground)] transition hover:text-[var(--foreground)]">
                      View all <ArrowRight className="h-4 w-4" />
                    </button>
                  </div>

                  <div className="grid auto-cols-[minmax(170px,1fr)] grid-flow-col gap-4 overflow-x-auto pb-2">
                    {(section.items || []).map((item) => (
                      <PosterCard
                        key={`${section.section}-${item.subject_id ?? item.slug ?? toDisplayTitle(item)}`}
                        item={item}
                        onOpen={() => openDetails(item)}
                        onPlay={() => playItem(item)}
                      />
                    ))}
                  </div>
                </section>
              ))
            )}
          </>
        )}
      </div>

      {selectedItem && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm">
          <div className="glass-panel relative max-h-[90vh] w-full max-w-4xl overflow-hidden rounded-[2rem] border border-white/10">
            <button
              onClick={() => {
                setSelectedItem(null);
                setDetail(null);
                setStreamUrl(null);
              }}
              className="absolute right-4 top-4 z-20 rounded-full border border-white/10 bg-black/30 p-2 text-white transition hover:bg-black/50"
            >
              <X className="h-4 w-4" />
            </button>

            <div className="grid gap-0 lg:grid-cols-[1.2fr_0.8fr]">
              <div className="relative min-h-[260px] overflow-hidden">
                <img src={toPosterUrl(selectedItem)} alt={toDisplayTitle(selectedItem)} className="h-full w-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-r from-black via-black/60 to-transparent" />
                {streamUrl ? (
                  <video
                    className="absolute inset-0 h-full w-full object-cover"
                    src={streamUrl}
                    controls
                    autoPlay
                    playsInline
                  />
                ) : null}
              </div>

              <div className="p-6">
                <div className="mb-3 inline-flex items-center gap-2 rounded-full border border-violet-500/30 bg-violet-500/10 px-3 py-1 text-[10px] uppercase tracking-[0.25em] text-violet-200">
                  <Star className="h-3.5 w-3.5 fill-yellow-400 text-yellow-400" />
                  {selectedItem.rating ?? detail?.imdbRatingValue ?? '8.9'}
                </div>

                <h3 className="text-3xl font-black text-[var(--foreground)]">{toDisplayTitle(selectedItem)}</h3>

                <div className="mt-3 flex flex-wrap gap-2 text-sm text-[var(--muted-foreground)]">
                  <span>{selectedItem.year ?? detail?.releaseDate?.slice(0, 4) ?? '2026'}</span>
                  <span>•</span>
                  <span>{detail?.type ?? selectedItem.type ?? 'Movie'}</span>
                  <span>•</span>
                  <span>{detail?.quality ?? selectedItem.badge ?? 'HD'}</span>
                </div>

                <p className="mt-5 text-sm leading-7 text-zinc-200">
                  {typeof detail?.description === 'string'
                    ? detail.description
                    : 'A cinematic story with premium streaming quality, fast metadata discovery, and direct-source playback powered by the Moviebox backend.'}
                </p>

                {aiSummary && (
                  <div className="mt-5 rounded-2xl border border-violet-500/30 bg-violet-500/10 p-3 text-sm leading-6 text-violet-50">
                    <div className="mb-1 text-[10px] uppercase tracking-[0.22em] text-violet-200">AI insight</div>
                    <p>{aiSummary}</p>
                  </div>
                )}

                <div className="mt-6 flex gap-3">
                  <button
                    onClick={() => playItem(selectedItem)}
                    className="inline-flex items-center gap-2 rounded-full bg-white px-4 py-2.5 text-sm font-semibold text-black transition hover:scale-[1.02]"
                  >
                    <Play className="h-4 w-4 fill-current" />
                    Play
                  </button>
                  <button
                    onClick={() => setStreamUrl(null)}
                    className="rounded-full border border-white/10 bg-white/5 px-4 py-2.5 text-sm font-semibold text-[var(--foreground)] transition hover:bg-white/10"
                  >
                    Close preview
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function PosterCard({
  item,
  onOpen,
  onPlay,
}: {
  item: MovieboxItem;
  onOpen: () => void;
  onPlay: () => void;
}) {
  return (
    <article className="group relative min-w-[170px] overflow-hidden rounded-[1.4rem] border border-white/10 bg-white/5 transition hover:-translate-y-1 hover:border-violet-400/40">
      <button onClick={onOpen} className="block w-full text-left">
        <div className="relative overflow-hidden">
          <img
            src={toPosterUrl(item)}
            alt={toDisplayTitle(item)}
            className="h-72 w-full object-cover transition duration-500 group-hover:scale-105"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />
        </div>
      </button>

      <div className="absolute inset-x-0 bottom-0 p-3">
        <div className="mb-2 flex items-center justify-between gap-2 text-[10px] uppercase tracking-[0.2em] text-zinc-200">
          <span className="rounded-full border border-white/15 bg-black/25 px-2 py-1">{item.badge || item.type || 'HD'}</span>
          <span className="rounded-full border border-yellow-400/30 bg-yellow-500/10 px-2 py-1 text-yellow-200">
            {item.rating ?? '8.9'}
          </span>
        </div>

        <button onClick={onOpen} className="block w-full truncate text-left text-base font-semibold text-white">
          {toDisplayTitle(item)}
        </button>

        <div className="mt-2 flex items-center justify-between text-xs text-zinc-300">
          <span>{item.year ?? '2026'}</span>
          <button
            onClick={onPlay}
            className="inline-flex items-center gap-1 rounded-full border border-violet-400/30 bg-violet-500/20 px-2 py-1 font-medium text-violet-100 transition hover:bg-violet-500/30"
          >
            <Play className="h-3 w-3 fill-current" />
            Play
          </button>
        </div>
      </div>
    </article>
  );
}
